INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p42432-gs424', 'stk-user462', 'GS 424', 'info', '{"desc": "اخذتها عند الدكتور الدامر …\nالقريدات من +A الى +B و في كم واحد اخذ B …\n\nالاختبار الاول كان صح و خطأ (20 سؤال) 20 درجه على الاختبار\nالاختبار الثاني كان صح و خطأ و سؤالين كتابه (20 سؤال صح و خطأ بـ 20 درجه) و 10 درجات على السؤالين\nالفاينل 4 اسئله كتابه (40 درجه على الفاينل) كل سؤال 10 درجات …\n\nالماده فهم لكن يبغى لها شويه تركيز و اذا كنت راعي حفظ … احفظها من اول صفحه الى اخر صفحه و تاخذ +A …\n\nيقولون العصيل احسن من الدامر بالقريدات و الله اعلم 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gs221-gs424/31708/6", "user": "user462", "ts": 1074998143000, "tid": 31708, "pn": 6}}', 1074998143000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
